export type DataImportPreview = { readonly "tableId": Id; readonly "revision": Revision; readonly "validation": "structure"; readonly "total": number; readonly "valid": number; readonly "invalid": number; readonly "samples": ReadonlyArray<DataImportSample>; readonly "errors": ReadonlyArray<DataImportRowError>; readonly "errorsTruncated": boolean; };

export type AccountDataImportPreview = { readonly "scope": EnvironmentScope; readonly "preview": DataImportPreview; };

export type DataImportExecution = { readonly "kind": "rows.import.apply"; readonly "commandId": Id; readonly "tableId": Id; readonly "revision": Revision; readonly "input": DataImportInput; readonly "access": { readonly "mode": "policy-preview"; readonly "userId"?: Id; }; readonly "confirmation"?: DataIdentifier; };

export type DataImportFailure = DataImportRowError | { readonly "row": number; readonly "code": "constraint_violation" | "policy_denied"; readonly "message": string; };

export type DataImportExecutionResult = { readonly "commandId": Id; readonly "tableId": Id; readonly "revision": Revision; readonly "total": number; readonly "inserted": number; readonly "updated": number; readonly "skipped": number; readonly "failed": number; readonly "errors": ReadonlyArray<DataImportFailure>; readonly "errorsTruncated": boolean; };

export type DataImportJobCreate = { readonly "kind": "import.enqueue"; readonly "commandId": Id; readonly "tableId": Id; readonly "revision": Revision; readonly "input": DataImportInput; readonly "access": { readonly "mode": "policy-preview"; readonly "userId"?: Id; }; readonly "confirmation"?: DataIdentifier; };

export type DataImportJobReceipt = { readonly "operationId": Id; readonly "revision": Revision; readonly "commandId": Id; };

export type DataImportJobView = { readonly "operation": Operation; readonly "tableId": Id; readonly "outcomeUnknown": boolean; readonly "result": DataImportExecutionResult | null; };

export type DataImportJobCancel = { readonly "commandId": Id; readonly "revision": Revision; };

export type DataImportServiceRequest = { readonly "scope": EnvironmentScope; readonly "bindingId": Id; readonly "operationId": Id; readonly "leaseId": Id; readonly "command": DataImportExecution; };

export type DataImportServiceResponse = { readonly "scope": EnvironmentScope; readonly "bindingId": Id; readonly "operationId": Id; readonly "leaseId": Id; readonly "result": DataImportExecutionResult | null; };

